INSERT INTO company_dossiers (ticker,status,description,lede,sells,revenue_model,opportunity,must_go_right,editor_note,bull_title,bull_json,bear_title,bear_json,thesis_breaker,financial_drivers_json,risks_json,monitor_json,questions_json,competitors,evidence_date,validated_at,published_at,updated_at) VALUES
('ASMB','published','Clinical-stage biotechnology company developing small-molecule antiviral therapies.','Assembly Biosciences develops oral antivirals intended to improve treatment of serious viral diseases, including herpesviruses and hepatitis-related programs, through wholly owned and partnered research. Clinical proof, partner economics, resistance profile and runway drive value.','Investigational small-molecule antiviral candidates and discovery programs.','Before approvals, economics depend on collaboration funding, license payments and milestones; successful wholly owned or partnered products could add royalties or product revenue.','Long-acting or mechanistically differentiated antivirals can improve suppression, convenience and resistance management in chronic viral disease.','Candidates must demonstrate antiviral activity, safety, durable dosing and a favorable resistance profile, while partnerships and cash fund larger trials.','Track patient-level virologic outcomes, dose and duration, resistance, safety, Gilead-related rights, milestone probability, cash burn and diluted ownership.','Differentiated antivirals can create focused clinical value','["Oral small molecules can offer practical chronic treatment.","Multiple viral targets diversify scientific opportunity.","A strategic collaboration can provide validation and non-dilutive funding."]','Early clinical and financing risk remain decisive','["Antiviral activity may not translate into durable clinical benefit.","Resistance or safety can limit dosing and combination use.","A small company remains dependent on partners and external capital."]','The thesis breaks if lead candidates lack differentiated antiviral activity or the company cannot finance regulator-agreed development','[{"label":"ANTIVIRAL PROOF","value":"Clinical value","detail":"Viral load, durability, dose, safety and resistance"},{"label":"PARTNER ECONOMICS","value":"Retained value","detail":"Rights, funding, milestones, royalties and development control"},{"label":"RUNWAY","value":"Survival constraint","detail":"Cash burn, trial timing and diluted shares"}]','[{"title":"Clinical and resistance","level":"High","text":"Candidate activity or resistance profile may be inadequate.","signal":"Complete data, breakthrough mutations and discontinuations"},{"title":"Regulatory","level":"High","text":"Endpoints and development requirements can expand time and cost.","signal":"FDA feedback, trial design and enrollment"},{"title":"Partner and financing","level":"High","text":"External decisions and capital availability affect program continuity.","signal":"Collaboration changes, runway and share issuance"}]','[{"title":"Lead-program evidence","text":"Require complete dose, durability, safety and resistance results.","impact":"BULL CASE"},{"title":"Runway to proof","text":"Compare cash and partner funding with the cost of decisive trials.","impact":"NEUTRAL"}]','["What clinical endpoint establishes differentiation from existing antivirals?","How durable is suppression and what resistance emerges?","Which milestones are reachable with present cash and partner funding?"]','Gilead Sciences, GSK, Moderna, Arbutus Biopharma and other antiviral developers.','2026-03-19','2026-08-05T05:08:00Z',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('ASML','published','Semiconductor-equipment company supplying lithography, metrology and computational systems used to manufacture advanced chips.','ASML is the sole commercial supplier of extreme-ultraviolet lithography and also sells deep-ultraviolet systems, metrology, software and installed-base services. Customer capital plans, system output, technology roadmaps and export controls drive value.','EUV and DUV lithography systems, metrology and inspection tools, computational lithography software, upgrades, parts and service.','High-value system sales plus recurring installed-base management, service, upgrades and software revenue.','Rising chip complexity and advanced-node capacity can increase lithography intensity, EUV adoption, High-NA demand and service revenue.','ASML must advance precision technology, expand supplier and manufacturing capacity, support customer yields and navigate export restrictions without losing roadmap leadership.','Bookings are volatile and not revenue. Track backlog quality, customer concentration, system shipments, gross margin, field acceptance, installed-base revenue, R&D and export licensing.','Unique lithography capability anchors advanced semiconductor production','["EUV is critical to leading-edge process technology.","A large installed base supports recurring service and upgrade economics.","Deep technical co-development creates substantial entry barriers."]','Customer concentration and geopolitics create material dependency','["A few chipmakers drive most advanced-system demand.","Export controls can restrict markets and service activity.","Roadmap delays, supplier constraints or customer yield problems can defer revenue."]','The thesis breaks if ASML loses roadmap leadership or export and customer constraints prevent its technology investment from producing durable cash returns','[{"label":"SYSTEMS / BOOKINGS","value":"Demand and delivery","detail":"EUV, High-NA and DUV orders, shipments, acceptance and backlog"},{"label":"INSTALLED BASE","value":"Recurring economics","detail":"Service, upgrades, utilization, field productivity and software"},{"label":"ROADMAP / CAPACITY","value":"Moat reinvestment","detail":"R&D, supplier output, cycle time, gross margin and export licenses"}]','[{"title":"Geopolitics and export controls","level":"High","text":"Government restrictions can limit shipments or support.","signal":"License decisions, China mix and service constraints"},{"title":"Customer cycle","level":"High","text":"A few customers can defer large capacity programs.","signal":"Bookings, backlog changes and customer capex"},{"title":"Technology and supply","level":"High","text":"Complex systems depend on roadmap execution and specialized suppliers.","signal":"Shipment timing, acceptance, yield and supplier bottlenecks"}]','[{"title":"EUV roadmap conversion","text":"Track High-NA and EUV shipments, acceptance and customer production use.","impact":"BULL CASE"},{"title":"Cash through the cycle","text":"Reconcile bookings and capacity spending with free cash flow and capital returns.","impact":"NEUTRAL"}]','["How much backlog is firm under customer schedule changes?","What production evidence validates High-NA economics?","How do export limits affect systems, service and long-term ecosystem scale?"]','Applied Materials, Lam Research, KLA, Canon, Nikon and customer internal process alternatives.','2026-02-25','2026-08-05T05:08:00Z',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('ASND','published','Commercial-stage biopharmaceutical company using TransCon prodrug technology to develop rare-endocrine therapies.','Ascendis Pharma commercializes endocrine medicines and advances additional TransCon programs. Patient starts, persistence, reimbursement, geographic launches, clinical evidence and manufacturing determine whether platform ambition converts to cash.','Long-acting endocrine therapies including SKYTROFA and YORVIPATH plus investigational TransCon programs.','Product sales through specialty channels, net of rebates and discounts, with possible collaboration, milestone and royalty economics.','Global launches, pediatric and adult adoption and additional rare-disease programs can leverage the TransCon platform and commercial infrastructure.','Ascendis must sustain access and adherence, expand labels, manufacture reliably, complete trials and fund launches while progressing toward self-financing.','Separate patient demand from stocking and gross-to-net effects; track starts, persistence, covered lives, geographic mix, inventory, gross margin, R&D and operating cash.','TransCon can build a multi-product endocrine franchise','["Long-acting delivery can improve convenience and adherence.","Two commercial platforms can share rare-endocrine infrastructure.","Additional programs can validate reusable technology."]','Launch execution and pipeline concentration remain demanding','["Payer restrictions and competing therapies can limit adoption.","Manufacturing or safety setbacks can affect concentrated products.","Multiple launches and trials require substantial cash and execution."]','The thesis breaks if commercial products fail to achieve durable patient use and cash generation while pipeline spending and dilution continue','[{"label":"PATIENT DEMAND","value":"Commercial proof","detail":"Starts, persistence, prescribers, indications and geography"},{"label":"ACCESS / NET PRICE","value":"Revenue quality","detail":"Coverage, rebates, discounts and net revenue per patient"},{"label":"PIPELINE / CASH","value":"Platform conversion","detail":"Clinical milestones, manufacturing, R&D and operating cash"}]','[{"title":"Commercial access","level":"High","text":"Payers and alternatives can restrict adoption or price.","signal":"Covered lives, denials, rebates and persistence"},{"title":"Product and manufacturing","level":"High","text":"Concentrated therapies depend on reliable supply and safety.","signal":"Batch release, inventory, adverse events and recalls"},{"title":"Pipeline and financing","level":"Medium","text":"Broad development can outpace commercial cash generation.","signal":"R&D, burn, milestones and share count"}]','[{"title":"Patient persistence","text":"Track sustained treated patients rather than launch shipments alone.","impact":"BULL CASE"},{"title":"Cash inflection","text":"Require product gross profit to fund launches and priority pipeline programs.","impact":"NEUTRAL"}]','["How many patients remain on therapy after the first year?","What net price remains after access support and rebates?","Which pipeline programs can be funded without delaying self-financing?"]','BioMarin, Pfizer, Takeda, Amgen, Rhythm Pharmaceuticals and other rare-endocrine therapy providers.','2026-02-11','2026-08-05T05:08:00Z',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('ASO','published','U.S. sporting-goods and outdoor-recreation retailer operating large-format stores and e-commerce.','Academy Sports + Outdoors sells national and private-label apparel, footwear, sports and outdoor products. Comparable sales, traffic, inventory, gross margin, new-store productivity and consumer demand drive owner returns.','Outdoor, sporting, fitness, apparel and footwear products from national brands and private labels.','Retail sales through stores and e-commerce, with margin determined by category, brand mix, promotions, shrink, freight and inventory turns.','Store expansion, localized assortments, omnichannel convenience and private-label penetration can grow sales and cash flow.','Academy must maintain value perception, open productive stores, manage seasonal inventory, control shrink and compete with specialists, mass merchants and online channels.','New stores can mask weak existing-store demand. Track comparable traffic and ticket, full-price sell-through, inventory aging, private-brand mix, shrink, leases and return on new-store capital.','Localized value retail can support disciplined expansion','["Broad assortments serve recurring family and recreation needs.","Private labels can differentiate value and support margin.","A repeatable store model can extend into underpenetrated markets."]','Consumer weakness and inventory mistakes can compress returns','["Discretionary categories are exposed to household budgets and weather.","Promotions, shrink and excess inventory can erode margin.","New stores may cannibalize or fail to reach expected productivity."]','The thesis breaks if store growth cannot offset deteriorating comparable demand and inventory investment while returns on new capital decline','[{"label":"COMPARABLE SALES","value":"Core demand","detail":"Traffic, ticket, category, region and e-commerce"},{"label":"INVENTORY / MARGIN","value":"Retail execution","detail":"Turns, markdowns, shrink, freight and private brands"},{"label":"NEW-STORE RETURNS","value":"Growth quality","detail":"Ramp sales, cannibalization, leases, capex and payback"}]','[{"title":"Consumer and weather","level":"High","text":"Discretionary demand can weaken or shift seasonally.","signal":"Traffic, categories, regions and promotions"},{"title":"Inventory and shrink","level":"High","text":"Poor forecasting and theft can reduce cash and margin.","signal":"Inventory growth, clearance and shrink rate"},{"title":"Expansion","level":"Medium","text":"New stores may underperform or cannibalize existing locations.","signal":"Cohort productivity, capex and returns"}]','[{"title":"Comparable demand","text":"Track traffic and full-price sell-through in mature stores.","impact":"NEUTRAL"},{"title":"Expansion economics","text":"Require each store cohort to meet payback and cash-return targets.","impact":"BULL CASE"}]','["How much growth comes from traffic versus price?","Are inventory and clearance aligned with category demand?","What return do recent store cohorts earn after all occupancy and capital costs?"]','Dick''s Sporting Goods, Bass Pro Shops, Walmart, Target, Amazon, specialty outdoor retailers and brand-owned channels.','2026-03-17','2026-08-05T05:08:00Z',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('ASPI','published','Development-stage advanced-materials company pursuing isotope-enrichment technologies for medicine, energy and other markets.','ASP Isotopes is building enrichment processes and facilities, principally in South Africa, for medical and industrial isotopes and related nuclear-energy opportunities. Technical qualification, customer contracts, regulation, capital and schedule credibility drive value.','Development programs and planned enriched isotopes for nuclear medicine, semiconductor, quantum and nuclear-energy uses.','The company is largely precommercial; future economics depend on isotope sales, supply agreements, licenses, partnerships and project financing.','Constrained isotope supply and strategic demand can support valuable domestic or allied production if processes scale economically.','Facilities must commission successfully, achieve required enrichment and purity, secure licenses, fulfill contracts and finance expansion without excessive dilution.','Treat capacity targets and agreements as hypotheses until verified by commissioned equipment, independent product qualification, binding customer terms, unit cost and delivered cash receipts.','Scarce-isotope supply can reward successful enrichment','["Medical and energy isotopes serve strategically important markets.","Modular processes may offer flexible capacity if technically proven.","Early supply agreements can validate customer interest."]','Technical, regulatory and financing risk are exceptionally high','["Pilot results may not scale to commercial purity and throughput.","Licensing and nuclear-material controls can delay operations.","Precommercial spending and related ventures can require repeated capital raises."]','The thesis breaks if plants cannot independently demonstrate commercial purity, throughput, cost and licensed customer delivery before capital is exhausted','[{"label":"TECHNICAL QUALIFICATION","value":"Core proof","detail":"Enrichment, purity, yield, throughput and independent validation"},{"label":"FACILITY / REGULATION","value":"Execution","detail":"Commissioning, permits, safeguards, schedule and capex"},{"label":"CONTRACTS / RUNWAY","value":"Commercial proof","detail":"Binding volume, pricing, customer qualification, cash and dilution"}]','[{"title":"Technology scale-up","level":"High","text":"Laboratory or pilot performance may not scale economically.","signal":"Third-party assays, throughput and unit cost"},{"title":"Regulation and schedule","level":"High","text":"Nuclear and isotope activities require extensive approvals and controls.","signal":"Licenses, inspections and commissioning milestones"},{"title":"Financing and governance","level":"High","text":"Pre-revenue projects and affiliates require substantial capital.","signal":"Burn, offerings, related parties and project funding"}]','[{"title":"Independent technical proof","text":"Require third-party evidence of product purity, throughput and repeatability.","impact":"BULL CASE"},{"title":"Cash-backed contracts","text":"Track binding customer commitments and receipts against facility capital needs.","impact":"BEAR CASE"}]','["What independently verified output has each facility produced?","Which contracts specify binding price, volume and qualification?","How much additional capital is required before positive operating cash flow?"]','Centrus Energy, Urenco, Orano, SHINE Technologies, established medical-isotope suppliers and government enrichment programs.','2026-04-10','2026-08-05T05:08:00Z',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('ASPN','published','Advanced-materials company producing aerogel products for electric-vehicle thermal barriers and energy infrastructure.','Aspen Aerogels applies silica aerogel technology to battery thermal barriers and industrial energy products. Customer programs, EV volumes, plant scale-up, product yield, gross margin and capital intensity determine owner value.','PyroThin battery thermal barriers and energy-industrial aerogel insulation products.','Product sales under automotive and industrial supply arrangements, with economics driven by program volume, pricing, material yield and factory utilization.','Battery safety requirements and energy-efficiency projects can expand aerogel adoption across vehicles and industrial infrastructure.','Aspen must convert automotive awards into production, diversify customers, ramp capacity on budget, maintain quality and achieve cash-generating yields.','Awarded programs are not shipped revenue. Track vehicle platforms, start-of-production, customer concentration, plant utilization, scrap, gross margin, capex, incentives and cash runway.','Aerogel engineering can solve difficult heat-management problems','["Thermal barriers address a critical battery-safety need.","Qualified automotive programs can generate multi-year volume.","Industrial insulation provides a second application base."]','Customer concentration and factory scale-up can overwhelm demand','["EV launch delays or program changes can reduce expected volume.","New capacity may suffer yield, quality or utilization problems.","Large capital needs and concentrated customers increase financing risk."]','The thesis breaks if awarded programs fail to convert into profitable shipments and new capacity cannot achieve stable yield and free cash flow','[{"label":"PROGRAM CONVERSION","value":"Demand proof","detail":"Awards, vehicle platforms, SOP timing, volumes and customers"},{"label":"YIELD / MARGIN","value":"Manufacturing proof","detail":"Utilization, scrap, quality, price and gross margin"},{"label":"CAPITAL / CASH","value":"Owner outcome","detail":"Plant capex, incentives, working capital and runway"}]','[{"title":"EV customers and timing","level":"High","text":"Platform volumes and launch schedules can change materially.","signal":"SOP, customer mix, orders and revisions"},{"title":"Manufacturing scale-up","level":"High","text":"New plants may miss yield, cost or quality targets.","signal":"Utilization, scrap, warranty and gross margin"},{"title":"Capital intensity","level":"High","text":"Capacity and working capital can require more financing.","signal":"Capex, burn, grants, debt and dilution"}]','[{"title":"Award-to-revenue bridge","text":"Track each program from qualification through production shipments.","impact":"BULL CASE"},{"title":"Factory cash economics","text":"Require stable yield and gross margin before valuing nameplate capacity.","impact":"NEUTRAL"}]','["Which customer programs are in firm production rather than awarded status?","What yield and utilization produce target gross margin?","How much capital remains before expansion becomes self-funding?"]','Autoneum, Morgan Advanced Materials, Cabot, thermal-management suppliers and alternative battery-barrier materials.','2026-03-13','2026-08-05T05:08:00Z',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('ASST','published','Public Bitcoin-treasury and asset-management company operating Strive Asset Management.','Strive seeks to increase Bitcoin per share while operating an investment adviser with ETFs and other mandates. Bitcoin price, financing terms, preferred obligations, asset-management flows and dilution determine common-owner outcomes.','Bitcoin treasury exposure plus ETFs, collective investment trusts, direct indexing and investment-advisory services.','Asset-management fees and investment results, combined with treasury gains or losses and financing through common, preferred or debt securities.','Scale in Bitcoin treasury and investment products can increase per-share exposure and recurring fees if capital is raised accretively.','Strive must custody assets securely, manage leverage and preferred claims, grow AUM, comply with securities rules and increase Bitcoin per diluted share rather than only total holdings.','Total Bitcoin is not the owner metric. Track Bitcoin per fully diluted share, purchase premium, common and preferred issuance, dividend obligations, AUM flows, fee rate and liquidity.','Accretive financing could compound Bitcoin per share','["Public-market access can fund treasury accumulation.","Asset management adds regulated distribution and fee potential.","Disciplined issuance below Bitcoin acquisition value can increase per-share exposure."]','Volatility, leverage and dilution can dominate the structure','["Bitcoin price declines can impair capital and financing access.","Preferred dividends and debt create fixed claims ahead of common owners.","Equity issuance can reduce Bitcoin per diluted share despite larger holdings."]','The thesis breaks if financing and operating costs cause Bitcoin per fully diluted common share and asset-management value to decline persistently','[{"label":"BITCOIN PER SHARE","value":"Primary owner metric","detail":"Holdings, cost basis, diluted shares, convertibles and treasury changes"},{"label":"CAPITAL STACK","value":"Risk structure","detail":"Preferred dividends, debt, maturities, liquidity and issuance terms"},{"label":"ASSET MANAGEMENT","value":"Operating value","detail":"AUM, flows, fee rate, expenses and regulatory capital"}]','[{"title":"Bitcoin volatility","level":"High","text":"Market declines can reduce asset value and financing capacity.","signal":"Price, collateral, liquidity and unrealized losses"},{"title":"Dilution and senior claims","level":"High","text":"Common and preferred financing can transfer value from common holders.","signal":"Bitcoin per share, dividends, issuance and conversions"},{"title":"Custody and regulation","level":"High","text":"Security failures or rule changes can disrupt treasury and advisory operations.","signal":"Custodian concentration, incidents and regulatory actions"}]','[{"title":"Per-share treasury audit","text":"Recalculate Bitcoin per fully diluted common share after every financing.","impact":"NEUTRAL"},{"title":"Fixed-claim coverage","text":"Compare liquidity and recurring fees with preferred dividends and debt obligations.","impact":"BEAR CASE"}]','["Did the latest financing increase Bitcoin per fully diluted share?","What cash sources cover preferred dividends during a Bitcoin drawdown?","Can the adviser grow profitable AUM independently of treasury valuation?"]','Strategy, MARA Holdings, Coinbase, Bitcoin ETFs and traditional asset managers.','2026-03-19','2026-08-05T05:08:00Z',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('ASTE','published','Manufacturer of equipment and components for aggregates, asphalt, concrete, roadbuilding and related infrastructure markets.','Astec Industries sells capital equipment and aftermarket parts used to process materials and build roads. Orders, backlog conversion, dealer and customer demand, parts mix, manufacturing efficiency and acquisition integration drive returns.','Crushing, screening, asphalt and concrete plants, roadbuilding machinery, mobile equipment, controls, parts and service.','Equipment sales plus recurring replacement parts, service and controls revenue through direct and dealer channels.','Infrastructure spending, aggregates demand, data-center construction and a larger installed base can support equipment and aftermarket growth.','Astec must deliver backlog on time, manage suppliers, improve factory productivity, integrate acquisitions and convert equipment demand into cash without excess inventory.','Backlog quality matters more than its headline size. Track cancellations, lead times, material cost, parts and service mix, factory absorption, working capital and return on acquisitions.','Installed equipment can support recurring aftermarket value','["Infrastructure equipment serves long-lived essential assets.","Parts and service can smooth equipment cycles and improve margin.","A broad product line can deepen dealer and customer relationships."]','Industrial cycles and execution can absorb backlog benefits','["Customers can defer large machines when financing or projects weaken.","Supply and factory inefficiency can delay shipments and compress margin.","Acquisitions and inventory can consume cash without adequate returns."]','The thesis breaks if backlog and infrastructure demand fail to generate durable margin, cash conversion and acceptable returns on invested capital','[{"label":"ORDERS / BACKLOG","value":"Demand visibility","detail":"Bookings, cancellations, lead time, segment and end market"},{"label":"MARGIN / AFTERMARKET","value":"Earnings quality","detail":"Parts, service, price-cost, utilization and productivity"},{"label":"WORKING CAPITAL","value":"Cash conversion","detail":"Inventory, receivables, customer deposits and operating cash"}]','[{"title":"Equipment cycle","level":"High","text":"Large capital purchases depend on projects and customer financing.","signal":"Orders, cancellations, dealer inventory and utilization"},{"title":"Manufacturing and supply","level":"High","text":"Complex production and components can disrupt delivery.","signal":"Lead times, overtime, expedite cost and margin"},{"title":"Acquisition and capital","level":"Medium","text":"Deals and inventory can reduce returns and cash.","signal":"Synergies, impairments, working capital and ROIC"}]','[{"title":"Backlog conversion","text":"Track delivery, cancellation and cash collection by segment.","impact":"BULL CASE"},{"title":"Aftermarket mix","text":"Require installed-base growth to raise parts and service margin.","impact":"NEUTRAL"}]','["How much backlog is cancellable or exposed to customer financing?","Are parts and service growing faster than equipment?","What cash return is earned on recent acquisitions and inventory investment?"]','Caterpillar, Deere, Terex, Metso, Sandvik, Wirtgen and specialized infrastructure-equipment makers.','2026-02-25','2026-08-05T05:08:00Z',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('ASTH','published','Physician-centric healthcare company operating risk-bearing provider networks, management services and care-delivery organizations.','Astrana Health manages patients through affiliated physician groups, IPAs, ACOs and care assets under capitated and value-based arrangements. Membership, premium yield, medical cost, quality bonuses and acquisition integration drive owner economics.','Population-health management, physician-network administration, care coordination, claims services and owned or affiliated clinical care.','Capitation and risk-pool payments from health plans, management fees, shared savings and fee-for-service care revenue.','Independent physicians and health plans can use Astrana infrastructure to manage more patients under value-based contracts across additional markets.','Astrana must control medical cost while maintaining quality, align physicians, price risk, integrate acquisitions, manage claims data and preserve regulatory compliance.','Revenue growth can include acquired premiums and medical expense. Track organic membership, per-member revenue, medical cost ratio, risk adjustment, reserves, shared savings, cash conversion and acquisition consideration.','Scaled physician infrastructure can improve value-based care','["Aligned physician networks can coordinate care and reduce avoidable cost.","Technology and claims capabilities can support independent practices.","Geographic expansion can spread infrastructure across more members."]','Medical risk and acquisitions can magnify execution errors','["Utilization or coding changes can exceed capitated payments.","Government and health-plan reimbursement rules can change.","Acquisitions may add contingent liabilities, debt and integration risk."]','The thesis breaks if membership growth fails to produce stable medical margins, quality outcomes and cash after acquisition and reserve adjustments','[{"label":"MEMBERSHIP / YIELD","value":"Revenue base","detail":"At-risk members, geography, payer, PMPM and organic growth"},{"label":"MEDICAL COST / QUALITY","value":"Care economics","detail":"Utilization, MCR, risk adjustment, reserves and shared savings"},{"label":"INTEGRATION / CASH","value":"Owner outcome","detail":"Acquisition contribution, contingent payments, debt and operating cash"}]','[{"title":"Medical cost and reserves","level":"High","text":"Utilization and claims development can exceed capitation.","signal":"MCR, reserve changes, admissions and specialty cost"},{"title":"Reimbursement and regulation","level":"High","text":"Government and payer rules affect revenue and risk adjustment.","signal":"Rate notices, audits, coding and contract terms"},{"title":"Acquisition integration","level":"High","text":"Rapid expansion can obscure organic performance and add liabilities.","signal":"Cohort margins, earn-outs, debt and goodwill"}]','[{"title":"Organic cohort economics","text":"Track membership, medical margin and quality by market before acquisitions.","impact":"BULL CASE"},{"title":"Claims and cash audit","text":"Reconcile reported earnings with reserve development and operating cash.","impact":"NEUTRAL"}]','["How much growth is organic membership versus acquired revenue?","What medical-cost assumptions support current capitation pricing?","Do acquired groups improve cash and quality after all integration costs?"]','agilon health, Privia Health, NeueHealth, UnitedHealth Optum, Humana CenterWell and regional provider groups.','2026-03-12','2026-08-05T05:08:00Z',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('ASTS','published','Space-based communications company building a satellite network intended to connect ordinary mobile phones directly through partner spectrum.','AST SpaceMobile is deploying large low-earth-orbit satellites and ground infrastructure for direct-to-device cellular broadband with mobile-network operators. Launch cadence, satellite performance, regulatory access, partner commercialization and funding determine value.','Space-based cellular broadband capacity and related government or commercial connectivity services.','Planned wholesale or revenue-sharing arrangements with mobile operators, plus possible government contracts and service revenue after network deployment.','Extending partner cellular coverage beyond terrestrial towers could address large geographic gaps without specialized handsets.','AST must manufacture and launch satellites reliably, achieve coverage and throughput, secure spectrum and country approvals, integrate with operators and finance a capital-intensive constellation.','Partner announcements are not recurring revenue. Track functioning satellites, beams and capacity, launch success, manufacturing output, regulatory approvals, commercial traffic, capex and diluted funding.','Direct-to-phone coverage could extend global mobile networks','["Using ordinary handsets lowers adoption friction.","Mobile-operator partnerships provide spectrum and distribution.","A space layer can cover areas uneconomic for terrestrial towers."]','Constellation execution and financing risk remain extreme','["Satellite or launch failures can delay coverage and destroy capital.","Capacity and service quality may not meet commercial expectations.","Spectrum, competitors and repeated equity or debt financing can impair owners."]','The thesis breaks if deployed satellites cannot deliver reliable economic service at scale before constellation funding materially dilutes or overleverages owners','[{"label":"SATELLITES / CAPACITY","value":"Technical proof","detail":"Built, launched and operational units, throughput, coverage and reliability"},{"label":"REGULATORY / PARTNERS","value":"Commercial access","detail":"Spectrum, country approvals, operator integration, contracts and traffic"},{"label":"CAPEX / FUNDING","value":"Owner survival","detail":"Cost per satellite, launches, cash, debt, grants and diluted shares"}]','[{"title":"Space and manufacturing","level":"High","text":"Complex satellites and launches can fail or slip.","signal":"Production rate, launch manifest, anomalies and in-orbit tests"},{"title":"Commercial and technical","level":"High","text":"Coverage, capacity or handset performance may be inadequate.","signal":"Service trials, latency, throughput, paying traffic and churn"},{"title":"Regulatory and financing","level":"High","text":"Approvals and constellation capital can take longer or cost more.","signal":"Licenses, capex, funding terms and dilution"}]','[{"title":"Operational constellation","text":"Track working satellites and verified capacity rather than planned launches.","impact":"BULL CASE"},{"title":"Funding per service milestone","text":"Compare capital raised and diluted shares with commercial coverage achieved.","impact":"BEAR CASE"}]','["What verified capacity and reliability does each deployed satellite deliver?","Which operator agreements contain binding commercial economics?","How much capital and dilution are required for continuous target-market coverage?"]','SpaceX Starlink Direct to Cell, Lynk Global, Globalstar, Iridium, terrestrial mobile networks and other satellite operators.','2026-03-02','2026-08-05T05:08:00Z',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)
